package tool

// Explain fact sheets (spec 063 US1, research R1): the read-only `explain`
// tool's deterministic answer path. Every sheet is composed HERE, tool-side,
// from the same registry entries and doctrine constants the mechanics run on
// — "described ≡ declared by construction", extended from the prompt surface
// (derive.go) to the player-facing answer path. The model chooses WHEN to
// call and how to converse around the answer; it can never alter the fact
// text itself (spec 063 standing resolution 3): zero model-generated bytes
// in any sheet (SC-001).
//
// This package is a leaf (spec 014 research R1), so doctrine that lives in
// other packages is MIRRORED here with a drift-pin test in the owning
// package — the established miracleKinds/clockSpeeds/PlanStepCap pattern:
//   - the charge economy (cap/genesis/regen) mirrors internal/sim's
//     GuardianChargeCap/GuardianGenesisCharges/GuardianChargeRegenTicks
//     (pinned by sim's TestExplainChargeDoctrineMirrorsSim);
//   - the decision-class vocabulary mirrors internal/toolloop's Verdict
//     constants (pinned by toolloop's TestExplainDecisionClassesMirrorVerdicts);
//   - the map-glyph legend mirrors internal/tui's mapGlyphs table (pinned by
//     tui's TestExplainGlyphsMirrorLegend).

import (
	"fmt"
	"sort"
	"strings"
)

// ExplainScope is the world slice a fact sheet describes (spec 063 FR-001):
// the sheet reflects the world's EFFECTIVE grant and stage ceiling — the
// roster facts describe THIS world, not the full catalog — while cataloged-
// but-ungranted tools are named as existing-but-ungranted (edge case: the
// sheet never pretends a tool doesn't exist, and never teaches a verb the
// world lacks without saying so).
type ExplainScope struct {
	// Granted is the world's effective granted roster in turn order — the
	// SAME slice that feeds the loop declaration, the derived guidance, and
	// the handler set (guardian grantedRoster + granted bundle tools), so
	// the sheet can never disagree with what the turn actually offers.
	// work_miracle arrives with its kind enum already narrowed (RestrictEnum).
	Granted []Tool
	// Catalog is the full declared guardian catalog (LoopRosterGuardian),
	// grant-independent — the honest-catalog half of the grant distinction.
	Catalog []Tool
	// Stage is the world's neutral curriculum stage id ("" = pre-ladder).
	Stage string
}

// explainTopics is the fixed topic vocabulary, in catalog order (data-model
// v1): per-topic sheets plus `<tool-id>` detail for any cataloged tool.
var explainTopics = []string{"roster", "costs", "charges", "workings", "decisions", "glyphs"}

// ExplainTopics returns a copy of the fixed topic vocabulary, in catalog
// order (the `<tool-id>` detail topics come from the live catalog and are
// not listed here).
func ExplainTopics() []string {
	out := make([]string, len(explainTopics))
	copy(out, explainTopics)
	return out
}

// The charge-economy doctrine constants, MIRRORED from internal/sim (leaf
// discipline; sim's TestExplainChargeDoctrineMirrorsSim pins all three).
const (
	explainChargeCap      = 3 // sim.GuardianChargeCap
	explainGenesisCharges = 1 // sim.GuardianGenesisCharges
	explainRegenGameHours = 6 // sim.GuardianChargeRegenTicks / 3600
)

// ChargeDoctrine exposes the mirrored charge-economy constants (cap, genesis
// grant, regeneration cadence in game hours) for the sim-side drift pin.
func ChargeDoctrine() (cap, genesis, regenGameHours int) {
	return explainChargeCap, explainGenesisCharges, explainRegenGameHours
}

// decisionClasses is the recorded verdict vocabulary (TASK-63 / spec 017
// data-model §5) with a player-facing meaning per class — MIRRORED from
// internal/toolloop's Verdict constants (toolloop's drift pin holds the name
// set equal). Order is the record.go declaration order.
var decisionClasses = []struct{ Name, Meaning string }{
	{"landed", "an act was admitted by its door and its events grounded — the turn's one act"},
	{"landed_clamped", "landed, after an over-long text field was trimmed to its cap first"},
	{"rejected_gate", "the door refused (no charge banked, bad target, night-only, not granted here) — nothing was spent; the ask can be repaired"},
	{"rejected_cardinality", "a second act arrived after one had already landed — one act per turn"},
	{"rejected_unknown", "the call named a tool this world does not offer"},
	{"rejected_malformed", "the arguments did not fit the tool's declared shape"},
	{"read_ok", "a read returned its data — free, never the act"},
	{"read_error", "a read failed — free, nothing changed"},
	{"unlanded", "the turn ended before the call could ground"},
}

// DecisionClassNames returns the mirrored verdict names in declaration order
// — the toolloop-side drift pin's enumeration surface.
func DecisionClassNames() []string {
	out := make([]string, len(decisionClasses))
	for i, d := range decisionClasses {
		out[i] = d.Name
	}
	return out
}

